package com.hospital.system.controller; import com.hospital.system.dto.PaymentRequest; import com.hospital.system.service.PaymentService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/bills/{billId}/payments") public class PaymentController {private final PaymentService s; public PaymentController(PaymentService s){this.s=s;} @GetMapping public Object all(@PathVariable Long billId){return s.all(billId);} @PostMapping public ResponseEntity<?> add(@PathVariable Long billId,@Valid @RequestBody PaymentRequest x){return ResponseEntity.status(201).body(s.add(billId,x));} }
